"""Macros (\\Vd...) for manuscript v2d (P. M. Vera's decisions on the Conclusions). No new computation: reads the frozen
one_word_items.csv (a945ed2) and the post hoc outputs already produced for v2c. Writes manuscrito_v2d/generated/numbers_v2d.tex.
Usage: python make_numbers_v2d.py <repo checkout at a945ed2>"""
import io, subprocess, sys
from pathlib import Path
import numpy as np, pandas as pd
REPO = Path(sys.argv[1]); COMMIT = "a945ed2cbdd9365fe346b262763f0262eaf686ea"; BASE = Path(__file__).resolve().parents[1]
import os; MS = BASE / os.environ.get("MS_DIR", "manuscrito_v2d"); PH = BASE / "posthoc_v2c"; XT = "visual_similarity_v2/agents_xtmem_v2/outputs/"
def csv(p): return pd.read_csv(io.BytesIO(subprocess.run(["git", "-C", str(REPO), "show", f"{COMMIT}:{p}"], capture_output=True, check=True).stdout))
W = "zero one two three four five six seven eight nine ten eleven twelve".split(); M = {}; N = 0
def check(c, w):
    global N; N += 1; print("OK  " if c else "FAIL", w); assert c, w
it = csv(XT + "one_word_items.csv"); c = it[(it.learner == "centroid") & (it.condition == "3sup")]
DOM = {"vegetables": "c1", "vehicles": "c2", "animals": "c3"}
c = c.assign(own=c.image.str[:2] == c.domain.map(DOM))
w = c[c.own & c.image.str.contains("_sup")].pivot_table(index=["domain", "image"], columns="encoder", values="accepted", aggfunc="first")
v, d = w["E2_vitsup"].astype(int), w["O1_dinov2b"].astype(int)
check(len(w) == 12 and v.sum() == 10 and d.sum() == 10, "ViT and DINOv2-base accept 10 of 12 within-domain candidates")
agree, differ = int((v == d).sum()), int((v != d).sum()); check(agree == 8 and differ == 4, "8 agreements, 4 disagreements")
print("  ViT only:", list(w.index[(v == 1) & (d == 0)]), " DINOv2-base only:", list(w.index[(v == 0) & (d == 1)]))
o = c[~c.own].groupby("encoder").accepted.agg(["sum", "size"])
check(o.loc["E2_vitsup", "sum"] == 0 and o.loc["O1_dinov2b", "sum"] == 20 and o.loc["E2_vitsup", "size"] == 48, "out of domain: ViT 0/48, DINOv2-base 20/48")
M["VdAgreeWord"], M["VdDifferWord"] = W[agree], W[differ]
# planned positive-control models and B1 (outputs of v2c, no refit)
T8 = ["R0_dinov2s","O1_dinov2b","R1_cvcl","E1_siglip","O2_openclip","E2_vitsup","E3_rn50sup","E4_mae"]
p02 = {e: pd.read_csv(PH / f"out/p02_{e}.csv") for e in T8 + ["F1_rn50rand0"]}
fr = {e: p02[e][p02[e].model == "pc_frozen_refit"].iloc[0] for e in p02}; im = {e: p02[e][p02[e].model == "pc_image_slope"].iloc[0] for e in p02}
check(all(fr[e].hi < 0 for e in p02), "planned models: negative slope, 95% CI below 0, for all 8 trained and the random network")
check(sum(im[e].estimate < 0 for e in T8) == 7 and sum(im[e].hi < 0 for e in T8) == 5, "B1: 7/8 negative, 5/8 CI entirely below 0")
check(sorted(e for e in T8 if im[e].lo < 0 < im[e].hi) == ["E4_mae", "O1_dinov2b", "R0_dinov2s"], "B1: CI includes 0 for DINOv2-small, DINOv2-base, MAE")
h = csv(XT + "broad_minus_narrow.csv"); h = h[(h.task == "one_word") & (h.learner == "centroid")].iloc[0]
check(f"{100*h.human_3sup:.2f}" == "77.49" and f"{100*h.human_3sub:.2f}" == "1.06" and f"{100*h.human_broad_minus_narrow:.2f}" == "76.43", "77.49 - 1.06 = 76.43 (unrounded difference)")
so = p02["R0_dinov2s"]; so = so[(so.model == "sup_only") & (so.re == "(1 | person) + (1 + zd | image)")].iloc[0]
print(f"  sup-only with by-image slopes: LR condition|distance chi2(3) = {so.LR_cond_given_dist:.2f}, p = {so.p_cond_given_dist:.3g}; LR distance|condition chi2(1) = {so.LR_dist_given_cond:.3f}, p = {so.p_dist_given_cond:.3f}; all three fits ok = {so.ok_all3}")
(MS / "generated").mkdir(exist_ok=True)
(MS / "generated/numbers_v2d.tex").write_text("% AUTO-GENERATED by scripts/make_numbers_v2d.py -- do not edit\n" + "".join(f"\\newcommand{{\\{k}}}{{{x}}}\n" for k, x in M.items()))
print(f"{len(M)} macros, {N} checks, 0 failures")
